const path = require("path");
const d = (f) => require(path.join(process.argv[2], "data", f));
const R = [...d("replies.json"), ...d("heldout-replies.json")];
const L = [...d("labels.json"), ...d("heldout-labels.json")];
const ids = process.argv[3] ? process.argv[3].split(",") : [];
for (const id of ids) {
  const r = R.find((x) => x.id === id), l = L.find((x) => x.id === id);
  console.log("#" + id, "[" + r.invoice.number, "$" + r.invoice.amount, "recv", r.received_at + "]", "->", l.category, l.rank, "=>", l.v0_category);
  console.log("  BODY:", JSON.stringify(r.body));
  console.log("  NOTE:", l.note);
}
const combos = {};
L.forEach((l) => { const k = l.category + " " + l.rank + " => " + l.v0_category; combos[k] = (combos[k] || 0) + 1; });
console.log(combos);

