    const [month, day] = [Number(us[1]) - 1, Number(us[2])];
    if (us[3]) {
      const year = us[3].length === 2 ? 2000 + Number(us[3]) : Number(us[3]);
      const d = new Date(Date.UTC(year, month, day));
      return d.getUTCMonth() === month ? isoDate(d) : null;
